(137, 'home', 'customer_testimonials', '{\"vi\":\"Kh\\u00e1ch H\\u00e0ng N\\u00f3i G\\u00ec V\\u1ec1 Ch\\u00fang T\\u00f4i\",\"en\":\"What Our Customers Say\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
