(139, 'home', 'testi1_role', '{\"vi\":\"Kh\\u00e1ch h\\u00e0ng th\\u00e2n thi\\u1ebft\",\"en\":\"Loyal customer\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(140, 'home', 'testi1_content', '{\"vi\":\"T\\u1eeb ng\\u00e0y d\\u00f9ng vi\\u00ean u\\u1ed1ng Omega-3 v\\u00e0 Collagen \\u1edf \\u0111\\u00e2y, s\\u1ee9c kh\\u1ecfe v\\u00e0 l\\u00e0n da c\\u1ee7a t\\u00f4i c\\u1ea3i thi\\u1ec7n r\\u00f5 r\\u1ec7t. R\\u1ea5t an t\\u00e2m v\\u00ec h\\u00e0ng chu\\u1ea9n ch\\u00ednh h\\u00e3ng, c\\u00f3 gi\\u1ea5y t\\u1edd r\\u00f5 r\\u00e0ng.\",\"en\":\"Since taking Omega-3 and Collagen pills here, my health and skin have improved significantly. Very secure because of genuine goods with clear documents.\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(141, 'home', 'testi2_name', '{\"vi\":\"Anh B\\u1ea3o Anh\",\"en\":\"Mr. Bao Anh\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(142, 'home', 'testi2_role', '{\"vi\":\"Nh\\u00e2n vi\\u00ean v\\u0103n ph\\u00f2ng\",\"en\":\"Office worker\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(143, 'home', 'testi2_content', '{\"vi\":\"Th\\u01b0\\u1eddng xuy\\u00ean m\\u1ea5t ng\\u1ee7 n\\u00ean t\\u00f4i \\u0111\\u01b0\\u1ee3c d\\u01b0\\u1ee3c s\\u0129 web t\\u01b0 v\\u1ea5n d\\u00f9ng th\\u1eed s\\u1ea3n ph\\u1ea9m h\\u1ed7 tr\\u1ee3 gi\\u1ea5c ng\\u1ee7. R\\u1ea5t hi\\u1ec7u qu\\u1ea3, ng\\u1ee7 s\\u00e2u gi\\u1ea5c v\\u00e0 s\\u00e1ng d\\u1eady kh\\u00f4ng m\\u1ec7t m\\u1ecfi. Giao h\\u00e0ng c\\u0169ng r\\u1ea5t nhanh.\",\"en\":\"Suffering from frequent insomnia, I was advised by the web pharmacist to try the sleep support product. Very effective, deep sleep and waking up not tired. Delivery is also very fast.\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(144, 'home', 'testi3_name', '{\"vi\":\"C\\u00f4 Mai Hoa\",\"en\":\"Ms. Mai Hoa\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(145, 'home', 'testi3_role', '{\"vi\":\"N\\u1ed9i tr\\u1ee3\",\"en\":\"Housewife\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(146, 'home', 'testi3_content', '{\"vi\":\"X\\u01b0\\u01a1ng kh\\u1edbp t\\u00f4i hay \\u0111au nh\\u1ee9c khi tr\\u1edf tr\\u1eddi. U\\u1ed1ng Glucosamine mua \\u1edf shop \\u0111\\u01b0\\u1ee3c 2 th\\u00e1ng nay th\\u1ea5y \\u0111\\u1ee1 h\\u1eb3n, \\u0111i l\\u1ea1i nh\\u1eb9 nh\\u00e0ng. C\\u00e1c b\\u1ea1n t\\u01b0 v\\u1ea5n r\\u1ea5t nhi\\u1ec7t t\\u00ecnh, chu \\u0111\\u00e1o.\",\"en\":\"My joints often ache when the weather changes. Taking Glucosamine bought at the shop for 2 months now feels much better, walking gently. The consultants are very enthusiastic and thoughtful.\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(147, 'home', 'info_title', '{\"vi\":\"Gi\\u1ea3i Ph\\u00e1p Ch\\u0103m S\\u00f3c S\\u1ee9c Kh\\u1ecfe To\\u00e0n Di\\u1ec7n\",\"en\":\"Comprehensive Health Care Solutions\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(148, 'home', 'info_desc', '{\"vi\":\"Ch\\u00fang t\\u00f4i t\\u1ef1 h\\u00e0o cung c\\u1ea5p c\\u00e1c d\\u00f2ng s\\u1ea3n ph\\u1ea9m th\\u1ef1c ph\\u1ea9m ch\\u1ee9c n\\u0103ng nh\\u1eadp kh\\u1ea9u ch\\u00ednh h\\u00e3ng t\\u1eeb M\\u1ef9, \\u0110\\u1ee9c, Ph\\u00e1p v\\u00e0 Nh\\u1eadt B\\u1ea3n. \\u0110\\u1ea3m b\\u1ea3o an to\\u00e0n, l\\u00e0nh t\\u00ednh v\\u00e0 mang l\\u1ea1i hi\\u1ec7u qu\\u1ea3 t\\u1ed1i \\u01b0u cho s\\u1ee9c kh\\u1ecfe c\\u1ee7a b\\u1ea1n v\\u00e0 gia \\u0111\\u00ecnh.\",\"en\":\"We are proud to provide genuine imported dietary supplement product lines from the US, Germany, France, and Japan. Ensuring safety, benignity, and optimal effectiveness for the health of you and your family.\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(149, 'home', 'info_li1', '{\"vi\":\"\\u0110\\u1ea1t chu\\u1ea9n ki\\u1ec3m \\u0111\\u1ecbnh an to\\u00e0n th\\u1ef1c ph\\u1ea9m GMP & FDA\",\"en\":\"Certified for food safety GMP & FDA\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(150, 'home', 'info_li2', '{\"vi\":\"C\\u00f4ng th\\u1ee9c t\\u1ed1i \\u01b0u sinh kh\\u1ea3 d\\u1ee5ng h\\u1ea5p thu nhanh\",\"en\":\"Optimal bioavailability formula for fast absorption\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
(151, 'home', 'info_li3', '{\"vi\":\"H\\u1ed7 tr\\u1ee3 t\\u01b0 v\\u1ea5n ph\\u00e1c \\u0111\\u1ed3 b\\u1ed5 sung d\\u01b0\\u1ee1ng ch\\u1ea5t mi\\u1ec5n ph\\u00ed\",\"en\":\"Free consultation for nutritional supplement regimen\"}', '2026-08-01 05:01:20', '2026-08-01 05:12:40'),
