INSERT INTO `product_categories` (`id`, `name`, `image`, `slug`, `description`, `meta_title`, `meta_keyword`, `meta_description`, `meta_robots`, `rel`, `target`, `status`, `created_at`, `updated_at`) VALUES
(1, '{\"vi\":\"Bổ sung Vitamin & Khoáng chất\",\"en\":\"Multivitamins & Essential Minerals\",\"fr\":\"Tieng phap\"}', 'images/products/s-l1600 (74).webp', 'bo-sung-vitamin-khoang-chat', '{\"vi\":\"<h1>Bổ Sung Vitamin &amp; Khoáng Chất – Nền Tảng Cho Cơ Thể Khỏe Mạnh</h1><p>Vitamin và khoáng chất là những dưỡng chất thiết yếu (micronutrients) đóng vai trò quan trọng trong hàng trăm quá trình sinh hóa của cơ thể: từ việc sản xuất năng lượng, củng cố hệ miễn dịch, bảo vệ hệ xương khớp cho đến việc làm chậm quá trình lão hóa. Tuy nhiên, chế độ ăn uống hàng ngày thường khó đáp ứng đầy đủ nhu cầu dinh dưỡng do thực phẩm bị mất chất trong quá trình chế biến hoặc do cơ thể hấp thu kém.</p><p>Tại <strong>HealthNutri</strong>, chúng tôi cung cấp giải pháp <strong>Bổ sung Vitamin &amp; Khoáng chất</strong> toàn diện, giúp bạn chủ động lấp đầy khoảng trống dinh dưỡng cho bản thân và gia đình mỗi ngày.</p><h3>Các Dòng Sản Phẩm Vitamin &amp; Khoáng Chất Tại HealthNutri</h3><ol start=\\\"1\\\"><li><p><strong>Vitamin Tổng Hợp (Multivitamins):</strong></p><ul><li><p>Giải pháp &quot;tất cả trong một&quot; chứa đầy đủ các vitamin và khoáng chất thiết yếu.</p></li><li><p>Công thức tối ưu hóa chuyên biệt theo độ tuổi và giới tính: Vitamin cho nam giới, nữ giới, trẻ em và người cao tuổi.</p></li></ul></li><li><p><strong>Các Loại Vitamin Đơn Lẻ Nổi Bật:</strong></p><ul><li><p><strong>Vitamin C:</strong> Tăng cường hệ miễn dịch, thúc đẩy sản sinh collagen và chống oxy hóa mạnh mẽ.</p></li><li><p><strong>Vitamin D3 &amp; K2:</strong> Tối ưu hóa việc hấp thụ canxi, bảo vệ sức khỏe xương và hệ tim mạch.</p></li><li><p><strong>Vitamin Nhóm B (B-Complex):</strong> Hỗ trợ chuyển hóa năng lượng, giảm căng thẳng (stress) và tăng cường chức năng hệ thần kinh.</p></li><li><p><strong>Vitamin E:</strong> Chăm sóc làn da, mái tóc và bảo vệ tế bào khỏi tác hại của gốc tự do.</p></li></ul></li><li><p><strong>Khoáng Chất Thiết Yếu:</strong></p><ul><li><p><strong>Canxi &amp; Magie:</strong> Củng cố mật độ xương, răng chắc khỏe và hỗ trợ chức năng cơ bắp.</p></li><li><p><strong>Kẽm (Zinc):</strong> Tăng sức đề kháng, hỗ trợ sức khỏe sinh lý và cải thiện sức khỏe làn da.</p></li><li><p><strong>Sắt (Iron):</strong> Bổ máu, ngăn ngừa tình trạng thiếu máu do thiếu sắt ở phụ nữ và nữ giới mang thai.</p></li></ul></li></ol><h3>Tại Sao Nên Chọn Mua Vitamin &amp; Khoáng Chất Tại HealthNutri?</h3><ul><li><p><strong>100% Chính Hãng &amp; Đạt Chuẩn GMP:</strong> Sản phẩm được kiểm định nghiêm ngặt về độ an toàn và hàm lượng dinh dưỡng.</p></li><li><p><strong>Hấp Thu Tối Đa:</strong> Sử dụng các dạng khoáng chất hữu cơ (Chelated) và dạng sinh học đạt độ hấp thu cao, thân thiện với hệ tiêu hóa.</p></li><li><p><strong>Tư Vấn Đúng Liệu Trình:</strong> Đội ngũ tư vấn viên tại HealthNutri luôn sẵn sàng lắng nghe nhu cầu và thể trạng của bạn để gợi ý sản phẩm phù hợp nhất, tránh việc bổ sung dư thừa không cần thiết.</p></li></ul>\",\"en\":\"<h1>Vitamin &amp; Mineral Supplements – The Foundation of Vibrant Health</h1><p>Vitamins and minerals are essential micronutrients that play vital roles in hundreds of bodily functions—from generating daily energy and strengthening the immune system to preserving bone density and protecting cells against oxidative stress. However, modern diets often fall short of delivering these vital nutrients due to food processing, lifestyle stress, or digestive absorption challenges.</p><p>At <strong>HealthNutri</strong>, our <strong>Vitamin &amp; Mineral Supplements</strong> collection provides comprehensive nutritional solutions designed to bridge these dietary gaps and empower your everyday vitality.</p><h3>Our Featured Vitamin &amp; Mineral Product Range</h3><ol start=\\\"1\\\"><li><p><strong>Multivitamins:</strong></p><ul><li><p>Convenient, all-in-one formulas containing balanced daily ratios of essential vitamins and minerals.</p></li><li><p>Tailored solutions tailored to specific demographics: Men’s Health, Women’s Health, Kids&#039; Wellness, and Senior Care.</p></li></ul></li><li><p><strong>Key Single &amp; Combination Vitamins:</strong></p><ul><li><p><strong>Vitamin C:</strong> Immunological support, collagen production, and potent antioxidant protection.</p></li><li><p><strong>Vitamin D3 &amp; K2:</strong> Synergistic support for optimal calcium absorption, bone strength, and cardiovascular health.</p></li><li><p><strong>Vitamin B-Complex:</strong> Essential for cellular energy production, nerve function, and stress management.</p></li><li><p><strong>Vitamin E:</strong> Deep cellular protection for healthy skin, hair, and anti-aging benefits.</p></li></ul></li><li><p><strong>Essential Minerals:</strong></p><ul><li><p><strong>Calcium &amp; Magnesium:</strong> Essential for strong bones, healthy teeth, and optimal muscle function.</p></li><li><p><strong>Zinc:</strong> Vital for immune response, skin clarity, and hormonal balance.</p></li><li><p><strong>Iron:</strong> Supports red blood cell formulation and combats fatigue and iron-deficiency anemia.</p></li></ul></li></ol><h3>Why Choose HealthNutri for Your Daily Supplements?</h3><ul><li><p><strong>Guaranteed Authenticity &amp; GMP Quality:</strong> Strictly tested formulations ensuring label accuracy, safety, and purity.</p></li><li><p><strong>High Bioavailability:</strong> Formulated with chelated minerals and bioactive vitamin forms for maximum intestinal absorption and digestive comfort.</p></li><li><p><strong>Expert Guidance:</strong> HealthNutri’s wellness specialists help you choose the right dosage and combination tailored to your unique lifestyle needs, avoiding unnecessary over-supplementation.</p></li></ul>\",\"fr\":\"<p>Tieng phap</p>\"}', '{\"vi\":\"Bổ sung Vitamin & Khoáng chất\",\"en\":\"Multivitamins & Essential Minerals\",\"fr\":\"Tieng phap\"}', '{\"vi\":\"vitamin và khoáng chất, bổ sung vitamin tổng hợp, thực phẩm bổ sung khoáng chất, vitamin chính hãng HealthNutri, viên uống bổ sung vitamin\",\"en\":\"vitamin and mineral supplements, multivitamins, essential minerals, HealthNutri vitamins, daily vitamin supplements\",\"fr\":\"Tieng phap\"}', '{\"vi\":\"Mua các dòng sản phẩm Bổ sung Vitamin & Khoáng chất chính hãng tại HealthNutri. Hỗ trợ tăng sức đề kháng, cải thiện thể trạng cho cả gia đình. Cam kết chuẩn GMP, giá tốt nhất.\",\"en\":\"Shop authentic Vitamin & Mineral Supplements at HealthNutri. Boost immunity, enhance energy, and support total body wellness for the whole family. GMP certified, premium quality.\",\"fr\":\"Tieng phap\"}', 'index,follow', 'dofollow', '_self', 0, '2026-07-27 04:53:06', '2026-08-06 04:34:54'),
(2, '{\"vi\":\"Hỗ trợ Miễn dịch & Đề kháng\",\"en\":\"Immunity & Resistance Support\"}', 'images/products/vitamin_c_shield.png', 'ho-tro-mien-dich-de-khang', '{\"vi\":\"<h1>Hỗ Trợ Miễn Dịch &amp; Đề Kháng – Lá Chắn Bảo Vệ Sức Khỏe Toàn Diện</h1><p>Hệ miễn dịch được coi là &quot;lá chắn tự nhiên&quot; giúp cơ thể chống lại sự tấn công của virus, vi khuẩn, ô nhiễm môi trường và các tác nhân gây bệnh từ bên ngoài. Tuy nhiên, thời tiết thay đổi thất thường, áp lực cuộc sống, chế độ ăn thiếu hụt dinh dưỡng và tình trạng căng thẳng kéo dài có thể khiến hệ miễn dịch suy yếu, làm cơ thể dễ mắc bệnh và lâu hồi phục.</p><p>Danh mục <strong>Hỗ trợ Miễn dịch &amp; Đề kháng</strong> tại <strong>HealthNutri</strong> mang đến các giải pháp chăm sóc sức khỏe chủ động, giúp củng cố hàng rào bảo vệ tự nhiên, cho bạn và gia đình luôn tràn đầy năng lượng và khoẻ mạnh mỗi ngày.</p><h3>Các Dòng Sản Phẩm Tăng Đề Kháng Nổi Bật Tại HealthNutri</h3><ol start=\\\"1\\\"><li><p><strong>Viên Uống &amp; Dưỡng Chất Tăng Miễn Dịch Tự Nhiên:</strong></p><ul><li><p>Chiết xuất từ các thảo dược thiên nhiên như Keo ong (Propolis), Xuyên tâm liên, Nấm Reishi (Linh chi), Đông trùng hạ thảo... giúp kích thích sản sinh tế bào miễn dịch tự nhiên.</p></li></ul></li><li><p><strong>Dưỡng Chất Vi Lượng Thiết Yếu:</strong></p><ul><li><p><strong>Vitamin C &amp; Kẽm (Zinc):</strong> Bộ đôi kinh điển giúp tăng cường hàng rào bảo vệ da và niêm mạc, thúc đẩy phản ứng miễn dịch nhanh chóng.</p></li><li><p><strong>Vitamin D3 High-Potency:</strong> Củng cố hoạt động của các tế bào T-cell – &quot;chiến binh&quot; tiêu diệt tác nhân ngoại nhập trong cơ thể.</p></li></ul></li><li><p><strong>Men Vi Sinh &amp; Hỗ Trợ Miễn Dịch Đường Ruột:</strong></p><ul><li><p>Hơn 70% tế bào miễn dịch nằm ở hệ tiêu hóa. Các dòng Probiotics chuẩn hóa giúp cân bằng vi sinh đường ruột, củng cố 70% sức mạnh miễn dịch từ bên trong.</p></li></ul></li><li><p><strong>Sản Phẩm Tăng Đề Kháng Chuyên Biệt Cho Trẻ Em &amp; Người Già:</strong></p><ul><li><p>Dạng siro, viên nhai hương vị thơm ngon cho trẻ em giúp bé ít ốm vặt, ăn ngon miệng.</p></li><li><p>Dạng viên uống bổ sung toàn diện cho người cao tuổi giúp phục hồi sức khỏe nhanh chóng sau khi ốm.</p></li></ul></li></ol><h3>Tại Sao Bạn Nên Chọn Sản Phẩm Tăng Đề Kháng Tại HealthNutri?</h3><ul><li><p><strong>Công Thức Tối Ưu &amp; Sinh Khả Dụng Cao:</strong> Sản phẩm được phối hợp thành phần khoa học, giúp cơ thể hấp thu nhanh chóng và mang lại hiệu quả rõ rệt.</p></li><li><p><strong>100% Chính Hãng &amp; An Toàn:</strong> Đạt chứng nhận GMP, có giấy công bố chất lượng từ Bộ Y tế, không gây tác dụng phụ khi sử dụng đúng liều lượng.</p></li><li><p><strong>Tư Vấn Đúng Nhu Cầu:</strong> Đội ngũ chuyên viên HealthNutri sẽ tư vấn dòng sản phẩm và lộ trình bổ sung phù hợp theo độ tuổi, thể trạng và mùa trong năm.</p></li></ul>\",\"en\":\"<h1>Immunity &amp; Resistance Support – Your Body&#039;s Ultimate Defense Shield</h1><p>The immune system serves as your body’s natural defense network against viruses, bacteria, environmental toxins, and daily fatigue. However, seasonal shifts, chronic stress, poor sleep, and nutritional gaps can compromise these defenses, leaving you vulnerable to frequent illnesses and sluggish recovery.</p><p>The <strong>Immunity &amp; Resistance Support</strong> collection at <strong>HealthNutri</strong> provides proactive healthcare solutions formulated to reinforce your natural immune response, helping you and your family stay resilient, energized, and protected year-round.</p><h3>Featured Immune-Boosting Categories at HealthNutri</h3><ol start=\\\"1\\\"><li><p><strong>Natural Botanical Immunity Boosters:</strong></p><ul><li><p>Formulated with high-potency herbal extracts such as Bee Propolis, Elderberry, Reishi Mushroom, and Cordyceps to stimulate natural white blood cell activity.</p></li></ul></li><li><p><strong>Essential Immune Micronutrients:</strong></p><ul><li><p><strong>Vitamin C &amp; Zinc Synergies:</strong> The gold-standard combo that strengthens epithelial barriers and accelerates immune defense response.</p></li><li><p><strong>High-Potency Vitamin D3:</strong> Activates T-cells to identify and neutralize foreign pathogens efficiently.</p></li></ul></li><li><p><strong>Gut-Immune Axis &amp; Probiotics:</strong></p><ul><li><p>Over 70% of the body’s immune system resides in the gut microbiome. Targeted probiotic formulas restore digestive equilibrium, elevating inner immunity.</p></li></ul></li><li><p><strong>Targeted Defense for Kids &amp; Seniors:</strong></p><ul><li><p>Delicious syrups and chewables for children to reduce seasonal sick days and support healthy growth.</p></li><li><p>High-absorption restorative supplements tailored for seniors and recovering individuals.</p></li></ul></li></ol><h3>Why Trust HealthNutri for Your Immune Health?</h3><ul><li><p><strong>Scientifically Formulated &amp; Highly Bioavailable:</strong> Combinations crafted for maximum absorption and optimal biological effectiveness.</p></li><li><p><strong>100% Certified &amp; Safe:</strong> Manufactured in GMP-compliant facilities with full regulatory compliance and transparent lab testing.</p></li><li><p><strong>Personalized Guidance:</strong> HealthNutri’s wellness experts assist you in choosing the ideal immune supplement based on age, lifestyle, and seasonal needs.</p></li></ul>\"}', '{\"vi\":\"Hỗ trợ Miễn dịch & Đề kháng\",\"en\":\"Immunity & Resistance Support\"}', '{\"vi\":\"thực phẩm tăng sức đề kháng, bổ sung miễn dịch, viên uống tăng đề kháng HealthNutri, siro tăng miễn dịch, sản phẩm bảo vệ sức khỏe miễn dịch\",\"en\":\"immune system supplements, immunity boosters, HealthNutri immune support, natural resistance supplements, wellness immunity supplements\"}', '{\"vi\":\"Khám phá các dòng sản phẩm Hỗ trợ Miễn dịch & Đề kháng chính hãng tại HealthNutri. Tăng cường lá chắn bảo vệ cơ thể trước vi kịch, vi khuẩn và tác nhân môi trường. Chuẩn GMP, an toàn cho cả gia đình.\",\"en\":\"Explore authentic Immunity & Resistance Support supplements at HealthNutri. Strengthen your body\'s natural defenses against pathogens and environmental stressors. Certified GMP, safe for all ages.\"}', 'index,follow', 'dofollow', '_self', 1, '2026-07-27 04:53:06', '2026-07-27 16:29:52'),
